const cfg = $('DISCOVERY — Runtime Config').first().json;
const items = Array.isArray($json.items) ? $json.items : [];

return items.map(v => ({
  json: {
    run_id: cfg.run_id,
    created_at: cfg.created_at,
    source_type: 'youtube',
    source_id: v.id,
    topic: v.snippet?.title || '',
    source_url: `https://www.youtube.com/watch?v=${v.id}`,
    channel: v.snippet?.channelTitle || '',
    published_at: v.snippet?.publishedAt || '',
    description: String(v.snippet?.description || '').slice(0, 1000),
    views: Number(v.statistics?.viewCount || 0),
    likes: Number(v.statistics?.likeCount || 0),
    comments: Number(v.statistics?.commentCount || 0),
    duration: v.contentDetails?.duration || '',
    rights_status: 'REVIEW_REQUIRED'
  }
}));

const cfg = $('DISCOVERY — Runtime Config').first().json;
return $input.all().map((item, index) => {
  const j = item.json || {};
  return {
    json: {
      run_id: cfg.run_id,
      created_at: cfg.created_at,
      source_type: 'google_trends',
      source_id: `trend-${index + 1}`,
      topic: String(j.title || '').trim(),
      source_url: String(j.link || j.guid || '').trim(),
      channel: 'Google Trends UK',
      published_at: j.isoDate || j.pubDate || '',
      description: String(j.contentSnippet || j.content || j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1000),
      views: 0,
      likes: 0,
      comments: 0,
      duration: '',
      rights_status: 'RESEARCH_ONLY'
    }
  };
}).filter(i => i.json.topic);

const rows = $input.all().map(i => i.json);
const seen = new Set();
const clean = [];

for (const row of rows) {
  const key = `${row.source_type}|${String(row.topic || '').toLowerCase().trim()}`;
  if (!row.topic || seen.has(key)) continue;
  seen.add(key);

  const engagement = row.views > 0
    ? ((row.likes + row.comments) / row.views) * 100
    : 0;

  clean.push({
    ...row,
    engagement_rate: Number(engagement.toFixed(3))
  });
}

clean.sort((a, b) => {
  if (a.source_type !== b.source_type) return a.source_type === 'youtube' ? -1 : 1;
  return (b.views || 0) - (a.views || 0);
});

const youtube = clean.filter(r => r.source_type === 'youtube').slice(0, 30);
const trends = clean.filter(r => r.source_type === 'google_trends').slice(0, 20);
const candidates = [...youtube, ...trends];

return [{
  json: {
    run_id: $('DISCOVERY — Runtime Config').first().json.run_id,
    created_at: $('DISCOVERY — Runtime Config').first().json.created_at,
    channel_theme: $('DISCOVERY — Runtime Config').first().json.channel_theme,
    candidate_count: candidates.length,
    candidates,
    candidates_text: candidates.map((r, i) =>
      `${i + 1}. ${r.topic}\nType: ${r.source_type}\nURL: ${r.source_url}\nChannel: ${r.channel}\nPublished: ${r.published_at}\nViews: ${r.views}\nLikes: ${r.likes}\nComments: ${r.comments}\nEngagement: ${r.engagement_rate}%\nDescription: ${r.description}`
    ).join('\n\n')
  }
}];

