const response = $json || {};
let text = response.output_text || '';

if (!text && Array.isArray(response.output)) {
  for (const out of response.output) {
    for (const c of (out.content || [])) {
      if (typeof c.text === 'string') {
        text = c.text;
        break;
      }
    }
    if (text) break;
  }
}

if (!text) throw new Error('OpenAI ranking response did not contain output text.');

const parsed = JSON.parse(text.replace(/```json|```/g, '').trim());
const items = Array.isArray(parsed.items) ? parsed.items : [];
const cfg = $('DISCOVERY — Runtime Config').first().json;

return items
  .filter(x => x && x.decision === 'review' && Number(x.trend_score || 0) >= 60)
  .slice(0, Number(cfg.max_candidates || 10))
  .map((x, index) => ({
    json: {
      run_id: cfg.run_id,
      created_at: cfg.created_at,
      candidate_rank: index + 1,
      topic: String(x.topic || ''),
      source_url: String(x.source_url || ''),
      source_type: String(x.source_type || ''),
      trend_score: Number(x.trend_score || 0),
      controversy_score: Number(x.controversy_score || 0),
      risk_level: String(x.risk_level || 'medium'),
      rights_status: String(x.rights_status || 'REVIEW_REQUIRED'),
      angle: String(x.recommended_angle || ''),
      hook: String(x.hook || ''),
      script: String(x.script || ''),
      clip_start: String(x.clip_start || ''),
      clip_end: String(x.clip_end || ''),
      status: 'Review',
      reason: String(x.reason || '')
    }
  }));

const records = Array.isArray($json.records) ? $json.records : [];

return records.map(record => {
  const f = record.fields || {};

  return {
    json: {
      airtable_record_id: record.id,
      topic: String(f.Topic || '').trim(),
      source_url: String(f.Source_URL || '').trim(),
      rights_status: String(f.Rights_Status || '').trim(),
      hook: String(f.Hook || '').trim(),
      script: String(f.Script || '').trim(),
      current_status: String(f.Status || '').trim()
    }
  };
});

const allowed = [
  'OWNED',
  'LICENSED',
  'CREATIVE_COMMONS_REVIEWED',
  'PLATFORM_REMIX_ALLOWED',
  'COMMENTARY_USE_APPROVED'
];

const item = {
  ...$json,
  rights_status: String($json.rights_status || '').trim().toUpperCase()
};

const required = [
  'airtable_record_id',
  'topic',
  'source_url',
  'rights_status',
  'hook',
  'script'
];

const missing = required.filter(key => !String(item[key] || '').trim());

return [{
  json: {
    ...item,
    valid: missing.length === 0 && allowed.includes(item.rights_status),
    validation_error: missing.length
      ? `Missing fields: ${missing.join(', ')}`
      : allowed.includes(item.rights_status)
        ? ''
        : `Rights status not approved: ${item.rights_status}`
  }
}];

const record = $input.first().json;
const fields = record.fields || {};

return [{
  json: {
    reference_id: String(record.id || ''),
    topic: String(fields.Topic || ''),
    source: {
      url: String(fields.Source_URL || ''),
      rights_status: String(fields.Rights_Status || '').trim().toUpperCase()
    },
    editorial: {
      hook: String(fields.Hook || ''),
      script: String(fields.Script || '')
    }
  }
}];

