parameters.jsCode:
const body = $json.body || $json;

const allowed = [
  'OWNED',
  'LICENSED',
  'CREATIVE_COMMONS_REVIEWED',
  'PLATFORM_REMIX_ALLOWED',
  'COMMENTARY_USE_APPROVED'
];

const required = ['reference_id', 'topic', 'source', 'editorial'];

const missing = required.filter(
  key => body[key] === undefined || body[key] === null
);

if (missing.length) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: `Missing: ${missing.join(', ')}`
    }
  }];
}

const sourceUrl = String(body.source?.url || '').trim();

const rightsStatus = String(
  body.source?.rights_status || ''
)
  .trim()
  .toUpperCase();

const topic = String(body.topic || '').trim();
const hook = String(body.editorial?.hook || '').trim();
const script = String(body.editorial?.script || '').trim();

if (!sourceUrl) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'Missing source.url'
    }
  }];
}

if (!allowed.includes(rightsStatus)) {
  return [{
    json: {
      valid: false,
      statusCode: 403,
      error: `Rights status not approved: ${rightsStatus}`
    }
  }];
}

const words = script
  .split(/\s+/)
  .filter(Boolean);

if (words.length < 25) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'Editorial script is too short.'
    }
  }];
}

/**
 * Prevent decimal values such as:
 * 3.58 million
 * 2.11%
 * 9.45%
 *
 * from being split as sentence endings.
 */
const protectedScript = script.replace(
  /(\d)\.(\d)/g,
  '$1<DECIMAL>$2'
);

/**
 * Split the script into sentences.
 */
const sentences =
  protectedScript
    .replace(/\s+/g, ' ')
    .match(/[^.!?]+[.!?]+|[^.!?]+$/g)
    ?.map(sentence =>
      sentence
        .replace(/<DECIMAL>/g, '.')
        .trim()
    )
    .filter(Boolean) || [script];

/**
 * Limit text by word count rather than character count.
 * This avoids long paragraphs and cuts at natural word boundaries.
 */
const limitWords = (value, maxWords) => {
  const textWords = String(value || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean);

  if (textWords.length <= maxWords) {
    return textWords.join(' ');
  }

  return `${textWords
    .slice(0, maxWords)
    .join(' ')}…`;
};

/**
 * Scene 1 remains the hook.
 *
 * Scene 2:
 * Opening context and initial evidence.
 *
 * Scene 3:
 * Supporting detail or explanation.
 *
 * Scene 4:
 * Final point, implication or CTA.
 */
const scene2Source = sentences
  .slice(0, 2)
  .join(' ');

const scene3Source = sentences
  .slice(2, 4)
  .join(' ');

const scene4Source = sentences
  .slice(4)
  .join(' ');

/**
 * Fallbacks ensure no scene is left blank when the script
 * contains fewer sentences than expected.
 */
const scene2Text = limitWords(
  scene2Source || script,
  12
);

const scene3Text = limitWords(
  scene3Source ||
  sentences.slice(1).join(' ') ||
  script,
  12
);

const scene4Text = limitWords(
  scene4Source ||
  'Follow for more.',
  10
);

return [{
  json: {
    valid: true,

    reference_id: String(body.reference_id),

    topic,

    source_url: sourceUrl,

    rights_status: rightsStatus,

    hook: limitWords(
      hook || topic,
      8
    ),

    script,

    scene_2_text: scene2Text,

    scene_3_text: scene3Text,

    scene_4_text: scene4Text,

    poll_attempt: 0
  }
}];

const approval = $('RENDER — Validate Approved Payload').first().json;

// Creatomate can be returned as a single render object by n8n,
// or as the first item when the API response is an array.
const renderId = $json?.id || $json?.data?.id || '';

if (!renderId) {
  throw new Error(`Creatomate did not return a render id. Response: ${JSON.stringify($json)}`);
}

return [{
  json: {
    ...approval,
    render_id: String(renderId),
    task_id: String(renderId),
    render_status: String($json?.status || 'planned'),
    poll_attempt: 0
  }
}];

const ctx = $('RENDER — Store Render Context').first().json;

let priorAttempt = Number(ctx.poll_attempt || 0);
try {
  if ($('RENDER — Increment Render Poll Attempt').isExecuted) {
    priorAttempt = Number($('RENDER — Increment Render Poll Attempt').last().json.poll_attempt || priorAttempt);
  }
} catch (_) {}

const status = String($json?.status || '').toLowerCase();
const processingStatuses = ['planned', 'waiting', 'transcribing', 'rendering'];

return [{
  json: {
    ...ctx,
    poll_attempt: priorAttempt,
    render_status: status || 'unknown',
    render_succeeded: status === 'succeeded',
    render_failed: status === 'failed',
    still_processing: processingStatuses.includes(status),
    render_url: String($json?.url || ''),
    render_error: String(
      $json?.error_message ||
      $json?.error ||
      (status === 'failed' ? 'Creatomate render failed.' : '')
    ),
    raw_render: $json
  }
}];

if (!$json.render_url) {
  throw new Error('Creatomate returned succeeded without a render URL.');
}

return [{
  json: {
    reference_id: $json.reference_id,
    task_id: $json.render_id,
    render_id: $json.render_id,
    status: 'Rendered',
    render_url: $json.render_url,
    topic: $json.topic,
    poll_attempt: $json.poll_attempt
  }
}];

const attempt = Number($json.poll_attempt || 0) + 1;
const retryAllowed = Boolean($json.still_processing) && attempt < Number($('RENDER — Community Setup').first().json.max_poll_attempts || 10);

return [{
  json: {
    ...$json,
    poll_attempt: attempt,
    retry_allowed: retryAllowed,
    error_log: retryAllowed
      ? ''
      : ($json.render_error || `Creatomate did not complete after ${attempt} polling attempts. Last status: ${$json.render_status || 'unknown'}`)
  }
}];

